import{_ as e,c as a,o as r,ag as o}from"./chunks/framework.Sr95JMjc.js";const _=JSON.parse('{"title":"E.164","description":"","frontmatter":{"title":"E.164","date":"2024-08-15T20:00+09:00","tags":["Phone Number"]},"headers":[],"relativePath":"posts/e164.md","filePath":"posts/e164.md","lastUpdated":1774774404000}'),l={name:"posts/e164.md"};function s(i,t,n,h,c,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h4 id="what-is-the-e-164-format" tabindex="-1">What is the E.164 format? <a class="header-anchor" href="#what-is-the-e-164-format" aria-label="Permalink to &quot;What is the E.164 format?&quot;">​</a></h4><p><strong>E.164</strong>는 전세계적으로 사용되는 국제전화번호에 대한 표준 형식이다. 문자 메시지 또는 왓츠앱 그리고 카카오 알림톡을 보내기 위해서 <a href="https://docs.aws.amazon.com/ko_kr/sns/latest/dg/sms_publish-to-phone.html" target="_blank" rel="noreferrer">발송 인터페이스 문서</a>를 확인해보면 휴대폰 번호 필드에 E.164 형식의 값을 요구하는 것을 확인할 수 있다. 글로벌 서비스나 솔루션을 준비한다면 프론트엔드에서도 <a href="https://github.com/jackocnr/intl-tel-input" target="_blank" rel="noreferrer">국가별 전화번호를 입력할 수 있는 컴포넌트</a>를 준비하는 편이다.</p><p><img src="https://file.okky.kr/images/1723708024170.png" alt=""></p><h4 id="_821012345678" tabindex="-1">+821012345678 <a class="header-anchor" href="#_821012345678" aria-label="Permalink to &quot;\\+821012345678&quot;">​</a></h4><ul><li>일반적으로 공백을 포함하지 않는 것으로 표현한다.</li><li>전화번호는 0으로 시작하는 부분은 생략한다.</li><li>한국의 국가 번호(country code)는 82 이며 이동통신망(area code)은 10 이다.</li><li>ITU-T의 E.164는 최대 15자리이다.</li></ul><h4 id="참고-링크" tabindex="-1">참고 링크 <a class="header-anchor" href="#참고-링크" aria-label="Permalink to &quot;참고 링크&quot;">​</a></h4><ul><li><a href="https://www.twilio.com/docs/glossary/what-e164" target="_blank" rel="noreferrer">What is E.164? | Twilio Docs</a></li><li><a href="http://www.ktword.co.kr/test/view/view.php?no=1970" target="_blank" rel="noreferrer">E.164 | 정보통신기술용어해설</a></li></ul>',7)])])}const m=e(l,[["render",s]]);export{_ as __pageData,m as default};
